export function BenefitsSection({
  heading = "{{heading}}",
  outcome1 = "{{outcome1}}",
  outcome2 = "{{outcome2}}",
  layout = "{{layout}}",
  accent = "{{accent}}",
}) {
  const listStyle = layout === "grid"
    ? { flexDirection: "row", flexWrap: "wrap" }
    : { flexDirection: "column" };
  const itemStyle = { display: "flex", gap: 8, alignItems: "flex-start", flex: layout === "grid" ? "1 1 200px" : "auto" };
  return (
    <section style={{ font: "16px/1.5 system-ui, sans-serif", color: "#241430", padding: 24 }}>
      <h2 style={{ margin: "0 0 16px", fontSize: 22, fontWeight: 700 }}>{heading}</h2>
      <ul style={{ listStyle: "none", margin: 0, padding: 0, display: "flex", gap: 12, ...listStyle }}>
        <li style={itemStyle}><span aria-hidden="true" style={{ fontWeight: 700, flexShrink: 0, color: accent }}>&#10003;</span>{outcome1}</li>
        <li style={itemStyle}><span aria-hidden="true" style={{ fontWeight: 700, flexShrink: 0, color: accent }}>&#10003;</span>{outcome2}</li>
      </ul>
    </section>
  );
}
